def document(name, title, sections):
    SPECS.append((name, title, sections))


def render(name, title, sections):
    d = Document()
    sec = d.sections[0]
    sec.top_margin = sec.bottom_margin = Cm(1.7)
    sec.left_margin = sec.right_margin = Cm(1.8)
    d.styles['Normal'].font.name = 'Arial'
    d.styles['Normal'].font.size = Pt(10)
    d.add_heading(title, 0)
    d.add_paragraph('pulse! | Университет Иннополис | 07.11.2026')
    styles = {
        'body': ParagraphStyle('body', fontName='CourseArial', fontSize=9.2, leading=12.8, spaceAfter=6),
        'title': ParagraphStyle('title', fontName='CourseBold', fontSize=20, leading=25, spaceAfter=12),
        'head': ParagraphStyle('head', fontName='CourseBold', fontSize=12, leading=16, spaceBefore=10, spaceAfter=6),
        'cell': ParagraphStyle('cell', fontName='CourseArial', fontSize=8.1, leading=10.7),
    }
    def para(t, kind='body'):
        return Paragraph(escape(str(t)).replace('\n', '<br/>'), styles[kind])
    story = [para(title, 'title'), para('pulse! | Университет Иннополис | 07.11.2026')]
    for heading, body in sections:
        d.add_heading(heading, 1)
        story.append(para(heading, 'head'))
        if isinstance(body, tuple):
            headers, rows = body
            table = d.add_table(rows=1, cols=len(headers))
            table.style = 'Table Grid'
            for c, text in zip(table.rows[0].cells, headers): c.text = str(text)
            for row in rows:
                for c, text in zip(table.add_row().cells, row): c.text = str(text)
            for row in table.rows:
                for c in row.cells:
                    for p in c.paragraphs:
                        for r in p.runs: r.font.size = Pt(8)
            width = A4[0] - 72
            # All text wraps; no clipped spreadsheet cells.
            pdf_table = Table([[para(c, 'cell') for c in row] for row in [headers, *rows]],
                              colWidths=[width / len(headers)] * len(headers), repeatRows=1, hAlign='LEFT')
            pdf_table.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#EDE5FA')),
                ('GRID', (0, 0), (-1, -1), .4, colors.HexColor('#C8CAD4')),
                ('VALIGN', (0, 0), (-1, -1), 'TOP'),
                ('LEFTPADDING', (0, 0), (-1, -1), 5),
                ('RIGHTPADDING', (0, 0), (-1, -1), 5),
                ('TOPPADDING', (0, 0), (-1, -1), 5),
                ('BOTTOMPADDING', (0, 0), (-1, -1), 5),
            ]))
            story.extend([pdf_table, Spacer(1, 8)])
        else:
            for line in body if isinstance(body, list) else [body]:
                d.add_paragraph(line)
                story.append(para(line))
    d.save(OUT / (name + '.docx'))
    def footer(canvas, doc):
        canvas.setFont('CourseArial', 8)
        canvas.drawString(36, 23, 'pulse! | 07.11.2026')
        canvas.drawRightString(A4[0]-36, 23, str(doc.page))
    SimpleDocTemplate(str(OUT / (name + '.pdf')), pagesize=A4, leftMargin=36, rightMargin=36,
                      topMargin=34, bottomMargin=37).build(story, onFirstPage=footer, onLaterPages=footer)


