def build():
    OUT.mkdir(exist_ok=True, parents=True)
    for name, filename in [('CourseArial','arial.ttf'), ('CourseBold','arialbd.ttf')]:
        pdfmetrics.registerFont(TTFont(name, str(Path('C:/Windows/Fonts') / filename)))
    prepare()
    baseline = OUT / 'baseline'; baseline.mkdir(exist_ok=True)
    for p in ROOT.glob('*.docx'): shutil.copy2(p, baseline / p.name)
    for p in (ROOT / 'deliverables').iterdir():
        if p.is_file() and p.suffix in ('.docx','.pod','.xml','.xlsx','.pdf') and not p.name.startswith('Кандидаты'):
            shutil.copy2(p, baseline / p.name)
    testing = OUT / 'testing'
    shutil.copytree(ROOT / 'deliverables/pulse-testing-debt-2026-11-07', testing, dirs_exist_ok=True)
    acceptance = ROOT / 'deliverables/acceptance-2026-11-07'
